@Route(value="pagos",layout=MainLayout.class) @PageTitle("Pagos | CitaCloud") @PermitAll
public class PagosView extends VerticalLayout {
 private final PagoService pagos; private final PacienteService pacientes; private final SucursalService sucursales; private final UUID empresa;
 private final Grid<Pago> grid=new Grid<>(Pago.class,false); private final PaginadorTabla<Pago> paginador=new PaginadorTabla<>(grid); private final TextField buscar=new TextField(); private final ComboBox<String> estado=new ComboBox<>(), metodoFiltro=new ComboBox<>(); private final Div resumen=new Div();
 public PagosView(PagoService pagos,PacienteService pacientes,SucursalService sucursales){this.pagos=pagos;this.pacientes=pacientes;this.sucursales=sucursales;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setWidthFull();setPadding(true);setSpacing(true);paginador.setFilasPorPagina(20);cabecera();tabla();cargar();}
 private void cabecera(){Button nuevo=new Button("+ Registrar pago",e->formulario());nuevo.addThemeVariants(ButtonVariant.LUMO_PRIMARY);HorizontalLayout titulo=new HorizontalLayout(new Div(new H2("Pagos"),new Paragraph("Consulta y gestión de los pagos recibidos.")),nuevo);titulo.setWidthFull();titulo.setJustifyContentMode(JustifyContentMode.BETWEEN);buscar.setPlaceholder("Paciente, expediente, no. pago o referencia");buscar.setClearButtonVisible(true);buscar.setWidth("min(100%, 360px)");buscar.addValueChangeListener(e->cargar());estado.setItems("Todos","Aplicado","Parcialmente reembolsado","Reembolsado","Anulado");estado.setValue("Todos");estado.setLabel("Estado");estado.setWidth("220px");estado.addValueChangeListener(e->cargar());metodoFiltro.setItems("Todos","EFECTIVO","TARJETA","TRANSFERENCIA","CHEQUE","OTRO");metodoFiltro.setValue("Todos");metodoFiltro.setLabel("Método");metodoFiltro.setWidth("190px");metodoFiltro.addValueChangeListener(e->cargar());HorizontalLayout filtros=new HorizontalLayout(buscar,metodoFiltro,estado);filtros.setWidthFull();filtros.setAlignItems(Alignment.END);filtros.getStyle().set("flex-wrap","wrap");add(titulo,filtros,resumen);}
 private void tabla(){grid.addColumn(this::codigo).setHeader("No. pago").setAutoWidth(true);grid.addColumn(Pago::getFecha).setHeader("Fecha");grid.addColumn(p->p.getPaciente()==null?"—":p.getPaciente().getNombreCompleto()).setHeader("Paciente").setFlexGrow(1);grid.addColumn(p->texto(p.getMetodoPago())).setHeader("Método");grid.addColumn(p->formatoMonto(p.getMonto())).setHeader("Monto");grid.addColumn(p->estadoVisual(p.getEstado())).setHeader("Estado");grid.addComponentColumn(p->{Button b=new Button("Detalle",e->detalle(p));b.addThemeVariants(ButtonVariant.LUMO_TERTIARY);return b;}).setHeader("Acciones");grid.setWidthFull();grid.setAllRowsVisible(true);grid.getStyle().set("flex","0 0 auto");add(grid,paginador);}
 private void cargar(){if(empresa==null){paginador.setItems(List.of());return;}String term=n(buscar.getValue());String filtroEstado=estadoInterno(estado.getValue());List<Pago> filtrados=pagos.listar(empresa).stream().filter(p->"Todos".equals(filtroEstado)||filtroEstado.equals(p.getEstado())).filter(p->"Todos".equals(metodoFiltro.getValue())||metodoFiltro.getValue().equals(p.getMetodoPago())).filter(p->term.isBlank()||n(codigo(p)).contains(term)||n(p.getReferencia()).contains(term)||(p.getPaciente()!=null&&(n(p.getPaciente().getNombreCompleto()).contains(term)||n(p.getPaciente().getNumeroExpediente()).contains(term)||n(p.getPaciente().getDocumento()).contains(term)))).toList();paginador.setItems(filtrados);PagoService.Resumen r=pagos.resumen(empresa);resumen.removeAll();resumen.add(new HorizontalLayout(tarjeta("TOTAL RECIBIDO",formatoMonto(r.totalRecibido())),tarjeta("PAGOS",String.valueOf(r.pagos())),tarjeta("PENDIENTE",formatoMonto(r.pendiente())),tarjeta("REEMBOLSADO",formatoMonto(r.reembolsado()))));}
 private void formulario(){if(empresa==null)return;Dialog d=new Dialog();d.setHeaderTitle("Registrar pago");d.setWidth("min(760px,96vw)");ComboBox<Paciente> paciente=new ComboBox<>("Paciente *",pacientes.listarActivos(empresa));paciente.setItemLabelGenerator(p->p.getNombreCompleto()+" · "+p.getNumeroExpediente());ComboBox<Sucursal> sucursal=new ComboBox<>("Sucursal",sucursales.listarActivas(empresa));sucursal.setItemLabelGenerator(Sucursal::getNombre);Grid<CargoFinanciero> cargos=new Grid<>(CargoFinanciero.class,false);cargos.setSelectionMode(Grid.SelectionMode.MULTI);cargos.addColumn(CargoFinanciero::getConcepto).setHeader("Concepto").setFlexGrow(1);cargos.addColumn(CargoFinanciero::getFecha).setHeader("Fecha");cargos.addColumn(c->formatoMonto(c.getSaldo())).setHeader("Pendiente");cargos.setAllRowsVisible(true);List<CargoFinanciero> cargosFiltrados=new ArrayList<>();int[] paginaCargos={0};ComboBox<Integer> filasCargos=new ComboBox<>("Filas por página");filasCargos.setItems(5,10,20,50);filasCargos.setValue(10);Button anteriorCargos=new Button("Anterior"),siguienteCargos=new Button("Siguiente");Span infoCargos=new Span();Runnable mostrarCargos=()->{int tamano=filasCargos.getValue()==null?10:filasCargos.getValue();int totalPaginas=Math.max(1,(int)Math.ceil((double)cargosFiltrados.size()/tamano));paginaCargos[0]=Math.min(paginaCargos[0],totalPaginas-1);int desde=paginaCargos[0]*tamano,hasta=Math.min(desde+tamano,cargosFiltrados.size());cargos.setItems(cargosFiltrados.subList(desde,hasta));infoCargos.setText(cargosFiltrados.isEmpty()?"Sin cargos pendientes":"Página "+(paginaCargos[0]+1)+" de "+totalPaginas+" · "+cargosFiltrados.size()+" cargos");anteriorCargos.setEnabled(paginaCargos[0]>0);siguienteCargos.setEnabled(paginaCargos[0]<totalPaginas-1);};filasCargos.addValueChangeListener(e->{paginaCargos[0]=0;mostrarCargos.run();});anteriorCargos.addClickListener(e->{if(paginaCargos[0]>0){paginaCargos[0]--;mostrarCargos.run();}});siguienteCargos.addClickListener(e->{paginaCargos[0]++;mostrarCargos.run();});HorizontalLayout paginacionCargos=new HorizontalLayout(filasCargos,infoCargos,anteriorCargos,siguienteCargos);paginacionCargos.setWidthFull();paginacionCargos.setJustifyContentMode(JustifyContentMode.END);BigDecimalField monto=campoMonto("Monto a pagar *"),efectivo=campoMonto("Efectivo recibido");efectivo.setRequiredIndicatorVisible(true);efectivo.setVisible(false);ComboBox<String> metodo=new ComboBox<>("Método *",List.of("EFECTIVO","TARJETA","TRANSFERENCIA","CHEQUE","OTRO"));TextField referencia=new TextField("Referencia");TextArea nota=new TextArea("Nota");nota.setMinHeight("96px");FormLayout datos=new FormLayout(paciente,sucursal,monto,metodo,efectivo,referencia,nota);datos.setResponsiveSteps(new FormLayout.ResponsiveStep("0",1),new FormLayout.ResponsiveStep("620px",2));datos.setColspan(nota,2);datos.setWidthFull();paciente.addValueChangeListener(e->{cargosFiltrados.clear();if(e.getValue()!=null)cargosFiltrados.addAll(pagos.pendientes(empresa,e.getValue().getId()));paginaCargos[0]=0;mostrarCargos.run();});cargos.addSelectionListener(e->{BigDecimal total=e.getAllSelectedItems().stream().map(CargoFinanciero::getSaldo).reduce(BigDecimal.ZERO,BigDecimal::add);monto.setValue(total);if("EFECTIVO".equals(metodo.getValue())&&(efectivo.getValue()==null||efectivo.getValue().compareTo(total)<0))efectivo.setValue(total);});monto.addValueChangeListener(e->{if("EFECTIVO".equals(metodo.getValue())&&efectivo.getValue()==null&&e.getValue()!=null)efectivo.setValue(e.getValue());});metodo.addValueChangeListener(e->{boolean esEfectivo="EFECTIVO".equals(e.getValue());efectivo.setVisible(esEfectivo);if(esEfectivo&&efectivo.getValue()==null&&monto.getValue()!=null)efectivo.setValue(monto.getValue());});Button confirmar=new Button("Confirmar pago",e->{try{List<PagoService.Aplicacion> apps=distribuir(cargos.getSelectedItems(),monto.getValue());Pago p=pagos.registrar(empresa,new PagoService.Solicitud(paciente.getValue()==null?null:paciente.getValue().getId(),sucursal.getValue()==null?null:sucursal.getValue().getId(),metodo.getValue(),monto.getValue(),efectivo.getValue(),referencia.getValue(),null,nota.getValue(),UUID.randomUUID().toString(),apps));getUI().ifPresent(ui->ui.getPage().open("/pagos/"+p.getId()+"/recibo","_blank"));d.close();cargar();Notification.show("Pago "+codigo(p)+" registrado correctamente.");}catch(Exception x){Notification.show(x.getMessage(),5000,Notification.Position.MIDDLE);}});confirmar.addThemeVariants(ButtonVariant.LUMO_PRIMARY);HorizontalLayout acciones=new HorizontalLayout(confirmar,botonCancelar(d));acciones.setWidthFull();acciones.setJustifyContentMode(JustifyContentMode.END);d.add(new VerticalLayout(datos,new H4("Cargos pendientes"),cargos,paginacionCargos));d.getFooter().add(acciones);d.open();}
 private void detalle(Pago p){Dialog d=new Dialog();d.setHeaderTitle("Detalle del pago · "+codigo(p));VerticalLayout c=new VerticalLayout(new Span(estadoVisual(p.getEstado())),new H2(formatoMonto(p.getMonto())),new Span("Paciente: "+(p.getPaciente()==null?"—":texto(p.getPaciente().getNombreCompleto()))),new Span("Método: "+texto(p.getMetodoPago())),new Span("Referencia: "+texto(p.getReferencia())));Button recibo=new Button("Imprimir recibo",e->getUI().ifPresent(ui->ui.getPage().open("/pagos/"+p.getId()+"/recibo","_blank")));Button reembolso=new Button("Reembolsar",e->reembolsar(d,p));reembolso.setVisible(!"VOIDED".equals(p.getEstado())&&!"REFUNDED".equals(p.getEstado()));c.add(new HorizontalLayout(recibo,reembolso));d.add(c);d.open();}
 private void reembolsar(Dialog detalle,Pago pago){Dialog d=new Dialog();d.setHeaderTitle("Reembolsar "+codigo(pago));d.setWidth("min(620px,96vw)");BigDecimalField monto=campoMonto("Monto a reembolsar *");monto.setValue(pago.getMonto()==null?BigDecimal.ZERO:pago.getMonto());ComboBox<String> metodo=new ComboBox<>("Método *",List.of("EFECTIVO","TARJETA","TRANSFERENCIA","CHEQUE","OTRO"));if(pago.getMetodoPago()!=null)metodo.setValue(pago.getMetodoPago());TextField referencia=new TextField("Referencia");TextArea motivo=new TextArea("Motivo *");motivo.setMinHeight("96px");FormLayout datos=new FormLayout(monto,metodo,referencia,motivo);datos.setResponsiveSteps(new FormLayout.ResponsiveStep("0",1),new FormLayout.ResponsiveStep("560px",2));datos.setColspan(motivo,2);Button confirmar=new Button("Confirmar reembolso",e->{try{pagos.reembolsar(empresa,pago.getId(),monto.getValue(),metodo.getValue(),referencia.getValue(),motivo.getValue());d.close();detalle.close();cargar();}catch(Exception x){Notification.show(x.getMessage());}});confirmar.addThemeVariants(ButtonVariant.LUMO_PRIMARY);HorizontalLayout acciones=new HorizontalLayout(confirmar,botonCancelar(d));acciones.setWidthFull();acciones.setJustifyContentMode(JustifyContentMode.END);d.add(datos);d.getFooter().add(acciones);d.open();}
 private BigDecimalField campoMonto(String etiqueta){BigDecimalField f=new BigDecimalField(etiqueta);f.setPrefixComponent(new Span("RD$"));return f;}
 private List<PagoService.Aplicacion> distribuir(Set<CargoFinanciero> seleccionados,BigDecimal monto){if(monto==null||monto.signum()<=0)throw new IllegalArgumentException("Indique un monto válido.");BigDecimal restante=monto;List<PagoService.Aplicacion> r=new ArrayList<>();for(CargoFinanciero c:seleccionados.stream().sorted(Comparator.comparing(CargoFinanciero::getFecha)).toList()){if(restante.signum()==0)break;BigDecimal aplicado=c.getSaldo().min(restante);r.add(new PagoService.Aplicacion(c.getId(),aplicado));restante=restante.subtract(aplicado);}if(restante.signum()>0)throw new IllegalArgumentException("El monto no puede superar el saldo pendiente seleccionado.");return r;}
 private Component tarjeta(String e,String v){Div d=new Div(new Span(e),new H3(v));d.getStyle().set("padding",".75rem 1rem").set("min-width","150px").set("border-radius","var(--lumo-border-radius-l)").set("background","var(--lumo-contrast-5pct)");return d;} private Button botonCancelar(Dialog d){Button b=new Button(VaadinIcon.CLOSE.create(),e->d.close());b.setTooltipText("Cancelar");b.getStyle().set("background-color","#e2e8f0").set("color","#1e293b");return b;} private String codigo(Pago p){if(p.getNumero()!=null&&!p.getNumero().isBlank())return p.getNumero();if(p.getFactura()!=null&&p.getFactura().getNumero()!=null)return p.getFactura().getNumero();return p.getId()==null?"—":"PAG-"+p.getId().toString().substring(0,8).toUpperCase(Locale.ROOT);} private String estadoInterno(String valor){return switch(valor==null?"Todos":valor){case "Aplicado"->"APPLIED";case "Parcialmente reembolsado"->"PARTIALLY_REFUNDED";case "Reembolsado"->"REFUNDED";case "Anulado"->"VOIDED";default->"Todos";};} private String estadoVisual(String valor){return switch(valor==null?"":valor){case "APPLIED"->"Aplicado";case "PARTIALLY_REFUNDED"->"Parcialmente reembolsado";case "REFUNDED"->"Reembolsado";case "VOIDED"->"Anulado";default->texto(valor);};} private String texto(String s){return s==null||s.isBlank()?"—":s;} private String n(String s){return s==null?"":s.toLowerCase(Locale.ROOT);} private String formatoMonto(BigDecimal m){return "RD$ "+NumberFormat.getNumberInstance(Locale.US).format(m==null?BigDecimal.ZERO:m.setScale(2,java.math.RoundingMode.HALF_UP));}
}


